insert into public.vendors (slug, name, role, status_label, status_tone, detail, cost_label, annual_cost, signed, risk_label, risk_tone, risk_points, sort) values
  ('kindbridge', 'Kindbridge', 'Helpline, text & chat', 'Live: In Progress', 'progress', 'Contract signed and countersigned. The 877-GAM-HALT number, live chat and text are being integrated onto the site now.', '$90,000 / year', 90000, true, 'Medium Risk', 'progress', array['$90K annual fee originally non-refundable — being renegotiated to quarterly payments.', 'Evergreen / auto-renewal clause flagged by counsel (Adam Kaplan); board proceeded anyway — status of the clause itself is unconfirmed.', 'Brianne has prior board history with Kindbridge — a disclosed conflict of interest the board is tracking.']::text[], 1),
  ('evive', 'Evive', 'Digital screening platform', 'Signed · Queued', 'done', 'Contract signed for a 12-month pilot. Integration begins roughly two weeks after Kindbridge goes fully live, so issues can be traced one change at a time.', '$25,000 / 12 months', 25000, true, 'Low Risk', 'done', array['12-month pilot signed, quarterly-friendly terms.', 'Integration intentionally sequenced after Kindbridge to isolate any issues.']::text[], 2),
  ('gamban', 'Gamban', 'Gambling-blocking software', 'In Legal Review', 'blocked', 'Terms set at a self-serve subscription rate. Final document is being converted to an editable format so counsel can redline before signature.', '$15,000 / year', 15000, false, 'Unsigned', 'blocked', array['$15K self-serve subscription rate agreed verbally.', 'Signature blocked purely on document format (needs editable Word, not PDF/DocuSign).']::text[], 3);
