insert into public.action_items (title, owner, status, due_date, note, sort) values
  ('Install Kindbridge chat/text code + swap site number to 877-GAM-HALT', 'Tareq', 'overdue', '2026-09-28', 'Target was Sep 28. Live site still shows the old 1-800-MY-RESET number as of Sep 29 — no chat or text widget yet.', 1),
  ('Remove Birches Health / fix SEO confusion on the live site', 'Brianne + Tareq', 'not_done', null, 'Birches Health is still listed as a treatment provider on /get-help — the exact thing causing the Kindbridge mix-up.', 2),
  ('Get Gamban contract into an editable format for redlining', 'Brianne / Matt', 'in_review', null, 'Blocked on DocuSign/PDF vs. an editable Word doc counsel can mark up.', 3),
  ('Begin Evive integration', 'Brianne + Tareq', 'blocked', '2026-10-12', 'Held until ~2 weeks after Kindbridge is fully live, so issues trace to one change at a time. Target ~Oct 12.', 4),
  ('Formalize founding-partner structure (Adam, Tareq, Jonathan, family office)', 'Adam + Tareq', 'open', null, 'Needed before any external GCSG raise. No date set.', 5),
  ('Put together a 2026 fundraising plan (tax-year timing)', 'Tareq', 'open', '2026-12-31', 'No plan circulated yet in meeting notes or email since the Sep 22 ask.', 6),
  ('Regain & use GCSG website backend access', 'Tareq', 'done', null, 'Kim granted Brianne admin access Sep 14; Brianne reset your login Sep 26.', 7);
insert into public.milestones (date_label, sort_date, title, detail, status, is_public, public_title, public_note, sort) values
  ('May 26', '2026-05-26', 'Mission/Vision Drafted', 'Group reviewed mission/vision/purpose. Fundraising email strategy introduced for the first time.', 'complete', true, 'Mission Drafted', 'Mission, vision and fundraising strategy set.', 1),
  ('Jun 9', '2026-06-09', 'Google Form Built · Event Strategy Mapped', 'Michael built donor interest Google Form. Two email versions drafted. Board meeting moved to Q3. September Responsible Gaming Month strategy outlined.', 'complete', false, null, null, 2),
  ('Jun 16', '2026-06-16', 'Fundraising Flow Finalized · Kindbridge Contract Flagged', 'Full donor flow locked in. Michael confirmed as point of contact. Kindbridge $90K contract flagged for review.', 'complete', false, null, null, 3),
  ('Jun 23', '2026-06-23', 'Info Deck Planned · Georgia Investor Column Added', 'Michael to build PDF info deck via Claude. Donor spreadsheet updated with Georgia Investor column.', 'complete', false, null, null, 4),
  ('Jun 30', '2026-06-30', 'Deck Reviewed · Strategy Shifted to Anchor Checks', 'Full deck reviewed. Slides 10 & 11 flagged for rework. Mass email delayed. Pivot to one-on-one anchor check outreach ($100K-$250K). Next meeting: Jul 16 at 4pm ET.', 'complete', false, null, null, 5),
  ('~Jul 8', '2026-07-08', 'Wexler Commits to Fund Year 1 — Operations Start Now', 'Wexler committed to fund full Year 1 (+ Year 2 if needed). $118K in account. Wexler to intro Michael + Brianne to major investors.', 'complete', false, null, null, 6),
  ('Jul 17', '2026-07-17', 'Vendor Stack Confirmed — 3-Vendor Integrated Model Locked', 'Kindbridge ($90K/yr) + Evive ($25K/12mo, corrected from 6mo) + Gamban ($15K/yr) = $130K. Integrated flow confirmed. HIPAA boundary defined. Kelly Ristler joins finance. Contract renegotiation initiated.', 'complete', true, 'Vendor Stack Confirmed', 'Three-vendor model locked at $130K/year.', 7),
  ('Jul 24', '2026-07-24', 'Contracts Negotiated — All Terms Accepted', 'Kindbridge: quarterly payments, 90-day out, monthly reports. Evive: 12-month pilot confirmed. Aug 1 launch target. Gamban arriving next week. Signatory authority being confirmed.', 'complete', false, null, null, 8),
  ('Aug 1', '2026-08-01', 'Sign Contracts + Launch', 'Kindbridge ($90K) and Evive contracts signed, with Matt Smith (Eight State) as signatory; Kindbridge countersignature dated Sep 1. Gamban still pending. Launch slid to late September to allow proper integration.', 'complete', true, 'Contracts Signed', 'Kindbridge and Evive executed.', 9),
  ('Aug 11', '2026-08-11', 'Investor Outreach Ramps Up — Atlanta Dinner & Signature Push', 'Michael secured verbal investor commitments (incl. Eric Dolorla, William Acres) ahead of Atlanta dinner; goal $2M+. Signature for GCSG (Wexler or Kelly) still the #1 blocker before further fundraising work. Group flagged NCPG''s funding controversy and agreed to stay mission-focused and keep distance from NCPG.', 'complete', false, null, null, 10),
  ('Aug 19', '2026-08-19', 'Contracts in Final Legal Review · Tareq Commits $100K', 'Kindbridge + Evive with counsel, no red flags. Evive invoice triggers 2-week integration. Tareq commits initial $100K. Membership/dues model raised for board. Spell Off Live raise emerges alongside GCSG fundraising.', 'complete', false, null, null, 11),
  ('End of Aug / Sep 1', null, 'Mass Email Blast + Responsible Gaming Month', 'Not sent. Donor outreach paused behind the Spell Off Live raise; press held until the helpline, text and chat are live (now mid-October).', 'deferred', false, null, null, 12),
  ('Sep 2', '2026-09-02', 'First Official Board Meeting', 'Quorum held. Kindbridge + Evive signed, Gamban under review. Alex Hall takes Elisa''s board seat; Tareq''s seat to be voted by email. Quarterly meetings per bylaws. Monthly vendor reporting starts October. Sweepstakes flagged as a scope question.', 'complete', true, 'First Board Meeting', 'Quorum held; vendor and governance recap.', 13),
  ('Sep 8', '2026-09-08', 'Gamban Finalized at $15K · Birches SEO Issue Found', 'Gamban terms set at $15K (self-serve subscription link). Googling Kindbridge returns Birches Health because of old GCSG site content — cleanup needed. Alex Hall takes over the weekly meeting link.', 'complete', false, null, null, 14),
  ('Sep 11', '2026-09-11', 'Kindbridge Kickoff — Go-Live MVP Defined', 'Georgia will use Kindbridge''s 877-GAM-HALT number. MVP = countersigned contract + number on site + go-ahead; phone, text and chat launch together. Georgia clinicians being hired. Marketing spend held for ~90 days of baseline data.', 'complete', true, 'Kindbridge Kickoff', 'Go-live MVP defined with Kindbridge’s team.', 15),
  ('Sep 22', '2026-09-22', 'Go-Live Plan Set · Staggered Rollout · Year 1 Funded', 'Kindbridge delivering chat/text code; Tareq to install. Weekly Kindbridge reports during integration. Evive starts 2 weeks after Kindbridge. Press moved to mid-October. Year 1 treated as funded; GCSG raise waits for Spell Off Live close and founding-partner structure.', 'complete', false, null, null, 16),
  ('Sep 28', '2026-09-28', 'Kindbridge Go-Live — Helpline, Text & Chat', 'Kindbridge code due end of week of Sep 22; Tareq to install it and swap in 877-GAM-HALT on the site. Status to confirm.', 'overdue', true, 'Go-Live Target', 'Helpline, text & chat swap — in progress.', 17),
  ('Pending', null, 'Gamban Contract Signed', 'Waiting on an editable Word version so counsel can redline (not DocuSign/PDF).', 'in_progress', false, null, null, 18),
  ('~Oct 12', '2026-10-12', 'Evive Integration Begins', 'Two weeks after Kindbridge goes live, so any issues can be traced to one change at a time.', 'upcoming', false, null, null, 19),
  ('October', '2026-10-01', 'First Monthly Vendor Reports', 'All three vendor contracts require monthly engagement reports (HIPAA-limited), starting in October. Kindbridge reporting weekly during integration.', 'upcoming', false, null, null, 20),
  ('Mid-Oct', '2026-10-15', 'Kindbridge Launch Press Announcement', 'After a few weeks of live operation. Local press first (AJC); Elisa helping on the release.', 'upcoming', false, null, null, 21),
  ('Mid-Oct', '2026-10-15', 'Clinical Staffing Report', 'Brianne to report Georgia clinician capacity with Kindbridge''s clinical team.', 'upcoming', false, null, null, 22),
  ('~Nov', '2026-11-01', 'Prevention vs. Treatment Recommendation', 'Brianne''s data-informed recommendation to the board after ~60 days of vendor data.', 'upcoming', false, null, null, 23),
  ('TBD', null, 'Founding-Partner Structure Formalized (Adam + Tareq)', 'Adam, Tareq, Jonathan Parente and the family office to set founding-partner roles and commitments before the external GCSG raise.', 'upcoming', false, null, null, 24),
  ('Q4 — TBD', '2026-12-28', 'Next Quarterly Board Meeting', 'Required by bylaws; being scheduled around Wexler''s calendar via Jonathan Parente.', 'upcoming', false, null, null, 25),
  ('~Late Dec', '2026-12-25', '90-Day Marketing / Advertising Review', 'Revisit advertising budget with ~90 days of baseline call data from Kindbridge.', 'upcoming', false, null, null, 26),
  ('Dec 31', '2026-12-31', 'Year-End Donation Deadline', 'Charitable donations generally must be made within the calendar year to count for 2026 taxes — timing for any 2026 GCSG raise.', 'upcoming', false, null, null, 27);
