insert into public.vendor_terms (vendor_slug, section, term, detail, risk_level, sort) values
  ('kindbridge', 'Cost', '$90,000 annual fee', 'Non-refundable, recognized in full upon signing. If we exit after 3 days, full $90K still owed. Brianne negotiating quarterly payments.', 'HIGH', 1),
  ('kindbridge', 'Cost', 'Quarterly payment option', 'Brianne negotiating with Dan — remove full upfront, shift to quarterly. Expect one quarter upfront for ramp-up.', 'MEDIUM', 2),
  ('kindbridge', 'Cost', 'Current account balance', '$118K in account as of Jul 8. Wexler committed to wire funds. Michael''s plan: wire another $100K, negotiate Kindbridge to ~$50K through year-end.', 'LOW', 3),
  ('kindbridge', 'Scope', '1-800-MY-RESET included', 'Kindbridge powers all of call/text/chat helpline — included in $90K. They built it and staff it.', 'LOW', 4),
  ('kindbridge', 'Terms', 'Auto-renewal clause', 'Non-renewal deadline was Sep 15 for term ending Jun 15, 2027. Being removed in renegotiation.', 'HIGH', 5),
  ('kindbridge', 'Terms', 'One-sided agreement', 'Adam Kaplan flagged multiple one-sided clauses. No first-year service minimums, limited reporting obligations. Being addressed in renegotiation.', 'MEDIUM', 6),
  ('kindbridge', 'Terms', 'Termination rights', 'No exit clause in original draft. Being added in renegotiation — Brianne expects Dan to accept.', 'MEDIUM', 7),
  ('kindbridge', 'HIPAA', 'Reporting limitations', 'GCSG can only receive aggregate KPIs (call volume, response rate, treatment acceptance). No PHI — demographic/clinical details create HIPAA liability.', 'LOW', 8),
  ('kindbridge', 'Negotiation', 'Position of strength', 'Brianne: ''We are in a position of strength.'' Dan wants the deal. Other entities have negotiated same concessions without problem.', 'N/A', 9),
  ('kindbridge', 'Next Steps', 'Renegotiation in progress', 'Brianne emailing Dan post-Jul 17 call. Kelly Ristler (Wexler CFO) joining negotiation for oversight. Conflict of interest: Brianne represents both GCSG and has prior Kindbridge board history.', 'ACTION', 10);
