insert into public.meeting_notes (meeting_slug, kind, body, owner, sort) values
  ('2026-09-22-gcsg-weekly', 'discussion', 'NH COUNCIL CONFERENCE — Brianne called in from the inaugural New Hampshire Council on Responsible Gambling conference (Chris Christie spoke; ~15 legislators attended), where she gave a speech and moderated a session between the new council and established service providers. Key takeaway: a healthy reminder not to get ahead of where an organization really is or put yourself out there before you have something concrete to offer. Fuller debrief deferred to next week. She also taught a session on prediction markets and gambling at her niece''s high school in Massachusetts.', null, 1),
  ('2026-09-22-gcsg-weekly', 'discussion', 'KINDBRIDGE INTEGRATION STATUS — Kickoff with Kindbridge''s full team went well. Kindbridge is writing the code needed for chat and text functionality alongside the helpline, expected ready by end of this week. Tareq has Brianne''s website login credentials (hasn''t logged in yet — will today) and will drop the code into the site backend. Decided NOT to update the phone number on the site early — number, text, and chat will all be switched on at once when the code is delivered. Target: live helpline, text, and chat in Georgia by next Monday (Sep 28).', null, 2),
  ('2026-09-22-gcsg-weekly', 'discussion', 'REPORTING — Contract calls for comprehensive monthly reports, but Brianne has asked Kindbridge for weekly reports during the initial integration period to monitor closely and help inform the Evive rollout.', null, 3),
  ('2026-09-22-gcsg-weekly', 'discussion', 'STAGGERED EVIVE ROLLOUT — Evive team meeting expected end of this week / early next week, but Evive will not integrate until two weeks after Kindbridge goes live — intentionally sequenced so that if something breaks, the team can pinpoint exactly what changed.', null, 4),
  ('2026-09-22-gcsg-weekly', 'discussion', 'PRESS ANNOUNCEMENT DELAYED — Brianne recommended holding the Kindbridge press announcement until a few weeks of live operation confirm everything is working; revisit around mid-October. No objections raised.', null, 5),
  ('2026-09-22-gcsg-weekly', 'discussion', 'GAMBAN CONTRACT SNAFU — Minor admin hurdle: Brianne needs the Gamban contract in an editable Word format so counsel can redline it, rather than DocuSign/PDF. Gamban isn''t thrilled but is accommodating because of the relationship. Not expected to be a real obstacle.', null, 6),
  ('2026-09-22-gcsg-weekly', 'discussion', 'FUNDRAISING ON HOLD BEHIND SPELL OFF LIVE — Spell Off Live has taken the front seat (investor call last week, another Thursday, distribution partner talks). Michael hasn''t reached back out to the GCSG donor list; most of those prospects will likely write checks to Spell Off Live. Michael''s recommendation: close out the Spell Off Live raise first, then return to those investors for GCSG with an updated budget, pitched around the tax-savings angle of charitable giving.', null, 7),
  ('2026-09-22-gcsg-weekly', 'discussion', 'FOUNDING PARTNERS STRUCTURE FIRST — Michael flagged that Adam wants to formalize Adam and Tareq as GCSG''s founding partners — mapping out a funding plan that works for both of them and the Council — before any external raise. The narrative to investors would then be: Adam and Tareq are founding members, Tareq has committed $X, here''s what the Council can do with $5M or $10M. Work needed on Adam''s, Jonathan Parente''s, and the family office''s end. Michael reiterated he''s transitioning back to venture capital, so this is his advice rather than a decision he''ll own.', null, 8),
  ('2026-09-22-gcsg-weekly', 'discussion', 'YEAR ONE IS FUNDED — Tareq told Brianne to operate on the assumption that year one is funded and she doesn''t need to raise to get things done. He expects a later raise to be easy since GCSG will be raising for something already live with data behind it.', null, 9),
  ('2026-09-22-gcsg-weekly', 'discussion', 'DATA BEFORE A SCALE BUDGET — Michael suggested starting to model an aggressive $5M budget. Brianne asked for more time: she can''t responsibly estimate advertising or scaling needs until she sees organic response with zero advertising across all three vendors. Michael agreed going slower is fine as long as that story is relayed to Adam, who tends to move fast.', null, 10),
  ('2026-09-22-gcsg-weekly', 'discussion', 'DONATION TIMING QUESTION — Michael suggested there was time since donors wouldn''t be writing checks until tax time next year; Alex and Tareq pushed back that charitable donations (at least via donor-advised funds) generally must be made within the calendar year to count. Implies any 2026 donor push needs to land before year-end.', null, 11),
  ('2026-09-22-gcsg-weekly', 'discussion', 'WHY A STATE GRANT MATTERS — Tareq asked Brianne to expand on her "no $500K state grant" comment from the Kindbridge call. Her answer: a recurring state line item for helpline/text/chat creates stability, letting other funds go to workforce development, aftercare, youth programs, etc. Without it, GCSG must re-secure the ~$90K Kindbridge baseline every year before anything else. She also noted short-term funding makes vendors hesitant to invest in building programs (citing Kindbridge''s reluctance on a one-year military/veterans grant).', null, 12),
  ('2026-09-22-gcsg-weekly', 'discussion', '"PRIZE PICKS CAP TABLE AS THE GRANT" — Tareq proposed reframing the Prize Picks cap table as GCSG''s equivalent of a recurring state grant — applying the same concept of ongoing commitments to that investor base. Flagged as a larger discussion for later.', null, 13),
  ('2026-09-22-gcsg-weekly', 'discussion', 'RAISE NOW, SPEND LATER — Michael noted GCSG could likely have $2M+ in the bank by Oct 15 if desired, and asked whether it''s better to raise now or wait for an organized plan. Brianne''s counsel: don''t spend for the sake of spending — hold funds until effectiveness is measured. Tareq added there''s no problem raising millions this year for tax reasons while not spending it right away. Tareq to start putting together a plan along those lines.', null, 14),
  ('2026-09-22-gcsg-weekly', 'discussion', 'ADMIN — Brianne spoke with Kelly, who had insurance questions; Brianne answered them and Kelly moved forward with the policy. Brianne is also handling admin items as Kelly sends them. FYI only for Alex — no follow-up needed.', null, 15),
  ('2026-09-22-gcsg-weekly', 'decision', 'Helpline number, text, and chat will all be switched on together once Kindbridge delivers the integration code — no early number swap. Target go-live Monday, Sep 28.', 'Agreed', 16),
  ('2026-09-22-gcsg-weekly', 'decision', 'Kindbridge to provide weekly reports during the initial integration period (contract baseline remains monthly).', 'Agreed', 17),
  ('2026-09-22-gcsg-weekly', 'decision', 'Evive integration to begin two weeks after Kindbridge is live.', 'Agreed', 18),
  ('2026-09-22-gcsg-weekly', 'decision', 'Kindbridge press announcement pushed to roughly mid-October, after a few weeks of live operation.', 'Agreed', 19),
  ('2026-09-22-gcsg-weekly', 'decision', 'GCSG outreach to the donor list to wait until the Spell Off Live raise closes and Adam/Tareq''s founding-partner structure is formalized.', 'Agreed', 20),
  ('2026-09-22-gcsg-weekly', 'decision', 'Year one is considered funded — Brianne should operate without fundraising pressure; raised funds should be held rather than spent until vendor data shows what to scale.', 'Agreed', 21),
  ('2026-09-22-gcsg-weekly', 'action', 'Tareq: Log in to the GCSG website backend today using Brianne''s credentials', 'Tareq', 22),
  ('2026-09-22-gcsg-weekly', 'action', 'Tareq: Implement Kindbridge''s chat/text code and swap in the helpline number once code is delivered (end of this week), targeting go-live Monday Sep 28', 'Tareq', 23),
  ('2026-09-22-gcsg-weekly', 'action', 'Kindbridge: Deliver chat/text integration code by end of this week', 'Kindbridge', 24),
  ('2026-09-22-gcsg-weekly', 'action', 'Brianne: Get the Gamban contract in an editable Word format for counsel to redline', 'Brianne', 25),
  ('2026-09-22-gcsg-weekly', 'action', 'Brianne + Tareq: Meet with the Evive team end of this week / early next week; hold integration until two weeks post-Kindbridge go-live', 'Brianne + Tareq', 26),
  ('2026-09-22-gcsg-weekly', 'action', 'Brianne: Revisit the Kindbridge launch press announcement around mid-October', 'Brianne', 27),
  ('2026-09-22-gcsg-weekly', 'action', 'Adam + Tareq + Jonathan + family office: Formalize Adam and Tareq''s founding-partner structure and funding commitments', 'Adam + Tareq', 28),
  ('2026-09-22-gcsg-weekly', 'action', 'Tareq: Put together a plan for raising funds this year (tax-year timing) while holding funds rather than spending immediately', 'Tareq', 29),
  ('2026-09-22-gcsg-weekly', 'action', 'Brianne: Share NH conference learnings and full debrief at next week''s call', 'Brianne', 30),
  ('2026-09-22-gcsg-weekly', 'action', 'Brianne: Build scaling/advertising budget once initial usage data from all three vendors is available', 'Brianne', 31),
  ('2026-09-11-ga-council-kick-off-meeting', 'discussion', 'KINDBRIDGE TEAM INTRODUCED — Kickoff call with Kindbridge Behavioral Health: Daniel Kaufmann (Founder/CEO), Michelle Hatfield (President/COO), Natalie Spiteri (Chief Clinical Officer), and Jenny Lebron (Program Manager, Helpline Services). Tareq introduced as Brianne''s integration right-hand, drawing on his Prize Picks background.', null, 1),
  ('2026-09-11-ga-council-kick-off-meeting', 'discussion', 'HELPLINE NUMBER DECISION — Georgia will use Kindbridge''s existing "Gamhalt" number (877-GAM-HALT) rather than the NCPG''s 800-MY-RESET or a newly purchased number. Calls will be tagged/categorized in Kindbridge''s CRM by originating state so Georgia-specific reporting stays clean — this is a first for Kindbridge (their other state programs each have dedicated numbers).', null, 2),
  ('2026-09-11-ga-council-kick-off-meeting', 'discussion', 'CALL ROUTING & RESOURCE LISTS — Kindbridge has already begun building Georgia-specific resource lists in advance of go-live; their system can already screen and route calls (help-seeking vs. misdialed customer service, gambling-specific vs. general addiction/mental health) the same way it does for Colorado and Florida (Playwise) programs.', null, 3),
  ('2026-09-11-ga-council-kick-off-meeting', 'discussion', 'CONTRACT STATUS — Countersigned contract needs to be re-sent by Matt Smith (Eight State) to Daniel/Kindbridge; Brianne will follow up with Matt. Not blocking planning, but required before go-live.', null, 4),
  ('2026-09-11-ga-council-kick-off-meeting', 'discussion', 'GO-LIVE SEQUENCING — Brianne wants phone, text, and chat to all launch together rather than a messy drip rollout — targeting roughly one to two weeks out ("two Mondays from now") rather than rushing. MVP for go-live is: signed/countersigned contract + Kindbridge''s number live on the GCSG website + a go-ahead signal to Kindbridge ("sign the contract, put our number on your website, and tell us to start").', null, 5),
  ('2026-09-11-ga-council-kick-off-meeting', 'discussion', 'TEXT & CHAT INTEGRATION (PHASE 2) — Text/chat are not yet enabled on the general Gamhalt number (only on Kindbridge''s Florida/Playwise-dedicated system) but can be enabled via Kindbridge''s CTM/CRM/HEPU platform. Live chat requires a widget embedded on the GCSG website that routes to Kindbridge''s engagement specialists; Jenny estimated about a week of dev work once her phone/CTM vendor provides the integration packet. Tareq will help with the website backend work; the former website consultant still hasn''t handed over credentials.', null, 6),
  ('2026-09-11-ga-council-kick-off-meeting', 'discussion', 'BIRCHES HEALTH / SEO CLEANUP — Acknowledged again that the GCSG website''s placeholder content (loaded pre-Brianne/Tareq) is causing the Birches Health / Kindbridge SEO confusion; will be cleaned up once site backend access is regained.', null, 7),
  ('2026-09-11-ga-council-kick-off-meeting', 'discussion', 'CLINICAL CAPACITY — Natalie is actively recruiting Georgia clinicians; one is already onboarded with several promising offers out, building capacity ahead of expected demand.', null, 8),
  ('2026-09-11-ga-council-kick-off-meeting', 'discussion', 'UNINSURED/UNDERINSURED TREATMENT FUND — GCSG did not initially fund a treatment subsidy pool for uninsured/underinsured clients (unlike some other state programs). Plan is data-driven: Kindbridge will track and flag patterns (how many people need treatment but can''t proceed due to cost/insurance) so Brianne and Tareq can size and justify establishing a subsidy pool once real numbers emerge.', null, 9),
  ('2026-09-11-ga-council-kick-off-meeting', 'discussion', 'REPORTING CADENCE — Confirmed goal of monthly reports covering total inbounds, gambling-specific vs. general inquiries, and insured/uninsured breakdowns — similar to Florida''s Playwise reporting. Group agreed to be skeptical of vanity/low-value call-volume metrics (e.g., NCPG counting 15-second calls) — the priority is genuine intakes, not inflated volume.', null, 10),
  ('2026-09-11-ga-council-kick-off-meeting', 'discussion', 'AFFECTED-OTHERS SUPPORT — Kindbridge already maintains resources for loved ones/affected others (Gam-Anon referrals, clinical support, educational literature — modeled on a dedicated Florida webpage). Brianne asked for example call-flow screenshots (one for a person struggling, one for an affected other) to help GCSG''s non-industry board members understand the caller experience; Michelle agreed to put this together.', null, 11),
  ('2026-09-11-ga-council-kick-off-meeting', 'discussion', 'MARKETING/ADVERTISING BUDGET — No dedicated marketing budget yet; plan is to launch quietly, gather 90 days of baseline call data, then reconvene to build an informed advertising plan (contrast with Florida''s ~$500K/yr Playwise marketing budget, funded by state grants GCSG doesn''t have). Kindbridge offered to share Florida''s marketing playbook for reference. First likely lever: asking fantasy operators to post GCSG''s number on their platforms.', null, 12),
  ('2026-09-11-ga-council-kick-off-meeting', 'discussion', 'PRESS TIMING — Group leaned toward not rushing a press announcement; better to wait until integration (phone + text + chat) is fully live for stronger coverage, and to avoid clashing with Kindbridge''s own upcoming press cycle (a major announcement Tuesday, plus a tech-shares co-op announcement about 1-2 weeks later) and September''s Responsible Gaming Education Month clutter. Leaning toward October for GCSG''s own coverage.', null, 13),
  ('2026-09-11-ga-council-kick-off-meeting', 'discussion', 'CALLER EXPERIENCE / BRANDING QUESTION — Raised that callers will hear "Thank you for calling Kindbridge Behavioral Health," not "Georgia Council," when they dial the Gamhalt number — flagged as something to address in GCSG''s website copy (e.g., "Call [number], brought to you by Kindbridge Behavioral Health") so users aren''t confused or feel misdirected.', null, 14),
  ('2026-09-11-ga-council-kick-off-meeting', 'discussion', '988 REFERRAL — Confirmed GCSG should list the 988 Suicide & Crisis Lifeline on its website; Kindbridge already refers to 988 routinely for acute cases and will continue to do so alongside GCSG referrals.', null, 15),
  ('2026-09-11-ga-council-kick-off-meeting', 'discussion', 'ADMIN / INVOICING — GCSG needs a dedicated council email address (currently using Brianne''s general email) and needs to connect Kindbridge''s accounting contact with Kelly (family office) to establish an invoicing process; Brianne to check with Kelly on requirements before making the handoff.', null, 16),
  ('2026-09-11-ga-council-kick-off-meeting', 'decision', 'Georgia will use Kindbridge''s existing Gamhalt number (877-GAM-HALT) for its helpline rather than a new number or the NCPG''s 800-MY-RESET.', 'Agreed', 17),
  ('2026-09-11-ga-council-kick-off-meeting', 'decision', 'Go-live MVP defined as: countersigned contract + Gamhalt number live on the GCSG website + go-ahead signal to Kindbridge; phone, text, and chat to launch together rather than in stages.', 'Agreed', 18),
  ('2026-09-11-ga-council-kick-off-meeting', 'decision', 'No dedicated marketing/advertising budget for now; will gather ~90 days of baseline call data before revisiting an advertising plan.', 'Agreed', 19),
  ('2026-09-11-ga-council-kick-off-meeting', 'decision', 'Treatment subsidy pool for uninsured/underinsured clients will be considered later, sized using real data from Kindbridge on cost-related drop-off patterns.', 'Agreed', 20),
  ('2026-09-11-ga-council-kick-off-meeting', 'decision', 'Press announcement to wait until full integration (phone + text + chat) is live, likely landing in October rather than during September''s Responsible Gaming Education Month or amid Kindbridge''s own press cycle.', 'Agreed', 21),
  ('2026-09-11-ga-council-kick-off-meeting', 'decision', '988 will be listed as a referral resource on the GCSG website.', 'Agreed', 22),
  ('2026-09-11-ga-council-kick-off-meeting', 'action', 'Brianne: Follow up with Matt Smith (Eight State) to re-send the countersigned contract to Daniel/Kindbridge', 'Brianne', 23),
  ('2026-09-11-ga-council-kick-off-meeting', 'action', 'Brianne + Tareq: Regain GCSG website backend access (chase former consultant''s credentials) to update the helpline number and prep for widget integration', 'Brianne + Tareq', 24),
  ('2026-09-11-ga-council-kick-off-meeting', 'action', 'Tareq: Coordinate with Kindbridge''s dev/phone (CTM) vendor to enable texting on the Gamhalt number and embed a live chat widget on the GCSG website', 'Tareq', 25),
  ('2026-09-11-ga-council-kick-off-meeting', 'action', 'Michelle: Prepare example call-flow screenshots (struggling caller vs. affected other) for the board', 'Michelle', 26),
  ('2026-09-11-ga-council-kick-off-meeting', 'action', 'Kindbridge (Jenny): Track and report patterns of uninsured/underinsured callers unable to proceed with treatment', 'Jenny/Kindbridge', 27),
  ('2026-09-11-ga-council-kick-off-meeting', 'action', 'Brianne: Draft website copy clarifying the Gamhalt number is "brought to you by Kindbridge Behavioral Health" to avoid caller confusion', 'Brianne', 28),
  ('2026-09-11-ga-council-kick-off-meeting', 'action', 'Brianne: Set up a dedicated GCSG council email address', 'Brianne', 29),
  ('2026-09-11-ga-council-kick-off-meeting', 'action', 'Brianne: Check with Kelly on invoicing requirements, then connect Kindbridge''s accounting contact with Kelly', 'Brianne', 30),
  ('2026-09-11-ga-council-kick-off-meeting', 'action', 'Kindbridge + GCSG: Clean up Birches Health / SEO issue once website backend access is regained', 'Brianne + Tareq', 31),
  ('2026-09-11-ga-council-kick-off-meeting', 'action', 'Group: Revisit marketing/advertising plan after ~90 days of baseline call data', 'Group', 32),
  ('2026-09-08-gcsg-weekly', 'discussion', 'SPELL OFF LIVE WRAP — Filming wrapped (season/series finale); described as a fun but bizarre show. Investor interest is growing off the show''s virality — Michael connected Adam with Ryan Seacrest, and Adam spoke with Simon Rex through a mutual contact. A lot of momentum at the top of Adam''s mind right now.', null, 1),
  ('2026-09-08-gcsg-weekly', 'discussion', 'ADAM''S TRAVEL WEEK — Adam covered Columbus (expects a big fight over online casino legalization there in 2027), meetings with the Texas delegation (Senator Cruz, Governor Abbott, the Secretary of Energy), and got an earful from a House member about the illegal gambling market. Missed a connecting flight and got stuck in Columbus/Orlando amid unrelated air-traffic disruption.', null, 2),
  ('2026-09-08-gcsg-weekly', 'discussion', 'FUNDRAISING STRATEGY — Michael and Alex met with Adam/Wexler in Atlanta. Adam''s expectation is that investors in Spell Off Live will also be encouraged (not required — framed as "would be nice/appreciated") to make a donation to GCSG, partly because those investors will need tax-season charitable deductions anyway. Adam reiterated strong confidence in Tareq''s continued involvement, both financially and as a decision-maker, citing his Prize Picks and problem-gambling background.', null, 3),
  ('2026-09-08-gcsg-weekly', 'discussion', 'GAMBAN CONTRACT — Finalized at $15K, the simplest of the three integrations (just a subscription link on the website for free Gamban downloads). Because GCSG doesn''t yet have a formal state self-exclusion program, the approach is self-serve: users can register for whatever subscription length feels appropriate rather than a program tied to a formal self-exclusion term. Gamban was co-founded by two friends of Brianne''s in recovery (now US-based, originally UK); Dan Umfleet (Kindbridge) worked at Gamban before founding Kindbridge — the RG vendor community is described as small and tightly connected.', null, 4),
  ('2026-09-08-gcsg-weekly', 'discussion', 'WEBSITE / SEO ISSUE WITH BIRCHES HEALTH — Dan Umfleet flagged that Googling "Kindbridge" is now returning Birches Health (a direct Kindbridge competitor) due to an SEO issue — apparently because the GCSG website is the only place online where the two names appear together (Birches had unexplainedly appeared in earlier deck slides). Urgent priority to regain GCSG website admin access (via Phil, from former vendors Kim/Celeste) to remove the Birches references before it causes real confusion for new vendor Kindbridge.', null, 5),
  ('2026-09-08-gcsg-weekly', 'discussion', 'THURSDAY LAUNCH CALLS — Two vendor launch/integration calls set for Thursday, Sep 10: Avive at 2:00pm ET (Sam Demello plus project manager Mike Bazzili, based in Ohio) and Kindbridge at 3:00pm ET (Dan Umfleet). Tareq confirmed availability for both. Plan to get all three vendors (Kindbridge, Avive, Gamban) on a joint call together in a couple of weeks to make sure they''re coordinated.', null, 6),
  ('2026-09-08-gcsg-weekly', 'discussion', 'NEXT BOARD MEETING — Per bylaws, another board meeting is required; needs to be scheduled around Wexler''s calendar, looping in Jonathan Parente.', null, 7),
  ('2026-09-08-gcsg-weekly', 'discussion', 'MEETING LINK TRANSITION — Elisa previously owned the weekly meeting calendar link; with her stepping back, Alex Hall volunteered to take over managing the weekly cadence and set up a new recurring invite.', null, 8),
  ('2026-09-08-gcsg-weekly', 'discussion', 'FINANCIAL RECORDKEEPING QUESTION — Kelly (family office) asked whether GCSG will use QuickBooks or another program for financial tracking, since she is doing check-cutting for donations. Brianne was caught off guard, having assumed Kelly was handling GCSG''s books/balance sheet entirely; Michael/Adam confirmed this is a reasonable question given the family office is still formalizing roles and workflows, and encouraged Brianne to follow up with Kelly for clarity rather than assume she''s missed something.', null, 9),
  ('2026-09-08-gcsg-weekly', 'discussion', 'ALEX HALL BACKGROUND — Alex is a lawyer (Vanderbilt) who has known Adam since the early days (including the original Dodgers program). He''ll be handling licensing/music-side work and reporting back to Adam, described as having more of a "Jonathan Parente mindset" — buttoned-up and process-oriented — and will likely coordinate closely with Parente and Kelly at the family office.', null, 10),
  ('2026-09-08-gcsg-weekly', 'discussion', 'MICHAEL''S TRANSITION — Michael''s original target of stepping back from ~15 responsibilities by September 15 will not happen on schedule; the transition will be gradual given how intertwined he is across teams. He''ll remain reachable and may take on a different role with Adam''s family office down the line (6–12 months out). He remains a key point of contact for potential donors at Underdog and Better, where he''s a substantial investor.', null, 11),
  ('2026-09-08-gcsg-weekly', 'discussion', 'NEXT FUNDRAISING TARGETS — Beyond personal contacts and Spell Off Live investors, the next tier of fundraising targets is Georgia-based fantasy sports operators — Prize Picks, Underdog, Better, Dabble, and Sleeper — to secure formal commitments given their products are highly accessible to consumers. Group acknowledged this will require actively making the case (not just assuming buy-in), especially with ownership/leadership changes at some of these companies (e.g., Underdog''s recent sale). Michael''s existing responsible-gaming relationships (Jeremy at Underdog and his RG lead Frank; Adam Warrington, formerly Prize Picks, now at Novig) seen as useful inroads.', null, 12),
  ('2026-09-08-gcsg-weekly', 'decision', 'Gamban contract finalized at $15K — simplest of the three vendor integrations (self-serve subscription link only, no formal self-exclusion program).', 'Agreed', 13),
  ('2026-09-08-gcsg-weekly', 'decision', 'Alex Hall to take over ownership of the weekly meeting calendar link going forward.', 'Agreed', 14),
  ('2026-09-08-gcsg-weekly', 'decision', 'Thursday, Sep 10 vendor launch calls confirmed: Avive at 2:00pm ET, Kindbridge at 3:00pm ET.', 'Agreed', 15),
  ('2026-09-08-gcsg-weekly', 'decision', 'Next board meeting must be scheduled per bylaws, coordinated around Wexler''s calendar.', 'Agreed', 16),
  ('2026-09-08-gcsg-weekly', 'decision', 'Broader fundraising push to formally approach Georgia-based fantasy operators (Prize Picks, Underdog, Better, Dabble, Sleeper) planned as the next outreach tier.', 'Agreed', 17),
  ('2026-09-08-gcsg-weekly', 'action', 'Brianne: Urgently chase Phil for website admin credentials (from former vendors Kim/Celeste) to remove Birches Health references and resolve the Kindbridge SEO/Google confusion', 'Brianne', 18),
  ('2026-09-08-gcsg-weekly', 'action', 'Brianne: Send the finalized Gamban PDF contract to Matt for legal review', 'Brianne', 19),
  ('2026-09-08-gcsg-weekly', 'action', 'Brianne: Email Jonathan Parente re: scheduling the next required board meeting around Wexler''s availability', 'Brianne', 20),
  ('2026-09-08-gcsg-weekly', 'action', 'Brianne: Follow up with Kelly to clarify financial recordkeeping process (QuickBooks vs. other) and confirm respective roles', 'Brianne', 21),
  ('2026-09-08-gcsg-weekly', 'action', 'Brianne + Tareq: Join Thursday''s two vendor launch calls — Avive (2pm ET) and Kindbridge (3pm ET)', 'Brianne + Tareq', 22),
  ('2026-09-08-gcsg-weekly', 'action', 'Tareq: Assist with reviewing/fixing the GCSG website backend once credentials are received', 'Tareq', 23),
  ('2026-09-08-gcsg-weekly', 'action', 'Alex: Set up a new recurring calendar invite/link for the weekly GCSG meeting', 'Alex', 24),
  ('2026-09-08-gcsg-weekly', 'action', 'Brianne: Work with Elisa on drafting a Kindbridge press release once launch calls are complete, targeting local and national press', 'Brianne', 25),
  ('2026-09-08-gcsg-weekly', 'action', 'Group: Prepare talking points on why RG investment benefits fantasy operators, ahead of formal outreach to Prize Picks, Underdog, Better, Dabble, and Sleeper', 'Group', 26),
  ('2026-09-02-gcsg-board-meeting', 'discussion', 'FIRST OFFICIAL BOARD MEETING — Quorum confirmed: Adam Wexler, Brianne, Matt Smith, Alex Hall, Chris DeConte, Kelly Ristler, Tareq Dowla, Michael Melikian, and Jonathan Parente (counsel, dialed in). Adam opened with GCSG''s origin story: born from early discussions with Brian and Keith White after Georgia was identified as the largest state without an NCPG-affiliated council; originally hoped a fantasy-sports operator coalition would lead it, then Adam took it on personally last summer.', null, 1),
  ('2026-09-02-gcsg-board-meeting', 'discussion', 'POSITIONING — GCSG is being built as the first digital-native problem gambling council and the aspiration is for it to become a model for other states, especially given the pace of change (DFS, day-trading/crypto, prediction markets) that legacy brick-and-mortar-oriented councils aren''t equipped to address.', null, 2),
  ('2026-09-02-gcsg-board-meeting', 'discussion', 'NCPG POLITICAL RISK — Michigan and Ohio regulators have already pulled affiliation with the National Council on Problem Gambling and are threatening state funding for any state council that stays affiliated with NCPG; three more states expected to follow. Georgia has no state grants to begin with, so GCSG''s private-donation model is, ironically, an advantage here — no political/litigation entanglement.', null, 3),
  ('2026-09-02-gcsg-board-meeting', 'discussion', 'SCALE OF THE PROBLEM — 52% of Gen Z respondents think gambling/exchanges are a good way to plan for their financial future. Inbound requests for help are running roughly 10–15x other platforms'' historical volumes, driven partly by blurred lines with day-trading apps like Robinhood and sports event contracts.', null, 4),
  ('2026-09-02-gcsg-board-meeting', 'discussion', 'KINDBRIDGE (VENDOR 1 — HELPLINE) — Contract signed at $90K (limited scope; declined the $30K workforce-development add-on and full treatment-coverage add-on for now pending integration data). Kickoff call next week with founder/CEO Dan Umfleet; ~2-week integration. Current NCPG-run number (1-800-MY-RESET) has 8.5–13 minute wait times and no referral capability — top priority is redirecting Georgians to Kindbridge ASAP, which requires regaining website admin access from a former contractor. Kindbridge will also expand the state''s mental health referral network via the Georgia Nanny Group (National Association of Mental Health Providers); currently only 2 trained clinicians in Georgia.', null, 5),
  ('2026-09-02-gcsg-board-meeting', 'discussion', 'EVIVE (VENDOR 2 — DIGITAL PORTAL) — Contract signed. Offers two pathways (cut back / abstain), a tracker, welfare checks, peer community, and a dedicated portal for affected others (spouses/children — historically ~60% of helpline calls in other states). Founder Sam Demello is himself in gambling recovery; Avive has 20 other state contracts and provides monthly engagement data. ~2-week integration/customization timeline, same as Kindbridge.', null, 6),
  ('2026-09-02-gcsg-board-meeting', 'discussion', 'GAMBAN (VENDOR 3 — BLOCKING SOFTWARE) — Contract received from Matt Zarb-Cousin, still under legal review (not yet signed — no clean PDF version yet for final review). Blocks ~75,000+ legal/illegal gambling and exchange sites; GCSG will build a self-exclusion program (state currently has none) and offer free Gamban subscriptions to Kindbridge helpline callers.', null, 7),
  ('2026-09-02-gcsg-board-meeting', 'discussion', 'PRESS / PR PLAN — Joint op-ed or press release with Kindbridge targeted for National Recovery Month (September), leaning on local press (AJC) rather than national trades, timed to the helpline cutover.', null, 8),
  ('2026-09-02-gcsg-board-meeting', 'discussion', 'REPORTING — Reporting requirements are built into all three vendor contracts (reviewed by counsel). Monthly engagement data begins in October (limited by HIPAA since this involves medical treatment data); will inform resource allocation decisions and feed a planned first annual report next year.', null, 9),
  ('2026-09-02-gcsg-board-meeting', 'discussion', 'BUDGET / 3-YEAR ROADMAP — Current ~$1.26M base budget funds roughly 3 years of the lean, 3-vendor model. Board discussed what expanded funding could unlock: more marketing/advertising channels, workforce development for more trained clinicians, and a treatment-subsidy pool for uninsured/underinsured individuals (~$850/person for a full outpatient course).', null, 10),
  ('2026-09-02-gcsg-board-meeting', 'discussion', 'SCOPE / VERTICALS — Mission centers on sports betting, DFS, fantasy, and prediction markets — explicitly not lottery, Class II machines, or day-trading/crypto apps (though individuals citing those alongside gambling issues won''t be turned away). Sweepstakes was flagged as a vertical not yet formally addressed in the mission/vision and should be added to future consideration — mixed legal/regulatory treatment nationally (some states ban it, some councils won''t take sweepstakes money).', null, 11),
  ('2026-09-02-gcsg-board-meeting', 'discussion', 'FUNDRAISING SOURCES — GCSG will be majority funded by private donors/owners rather than operators. Operator dollars (FanDuel, DraftKings, etc.) are seen as limited and more about reputational cover than material funding; sweepstakes operators (cash-flow positive) and forward-thinking platforms were flagged as more promising outreach targets. Membership program idea (modeled on the Massachusetts Partnership for Responsible Gaming that Brianne previously built) discussed as a longer-term option — informal conversations first, formal proposal to come back to a future board meeting.', null, 12),
  ('2026-09-02-gcsg-board-meeting', 'discussion', 'SPELL OFF FUNDRAISE — Adam and Michael are prioritizing a fundraise for the "Spell Off" project next week, primarily targeting Prize Picks investors interested in tax-minimization strategies; hope is that GCSG can also benefit from that donor pool. First six investor conversations were extremely positive.', null, 13),
  ('2026-09-02-gcsg-board-meeting', 'discussion', 'PREVENTION VS. TREATMENT BALANCE — Brianne requested 60 days post-launch data before recommending how to balance prevention/education spend vs. treatment/recovery spend, citing Pennsylvania''s recent finding that 20% of "mixed-mode" gamblers have a gambling problem (double the general average) as an example of how data should drive resource allocation.', null, 14),
  ('2026-09-02-gcsg-board-meeting', 'discussion', 'MISSION/VISION UPDATE — Board revisited whether to explicitly position GCSG as "the model" council nationally, and whether to add "where younger generations are protected" language, prompted by data showing 36% of 11–17 year-olds have gambled and 60% saw gambling content on social media unprompted. Adam plans to test this "model council" framing at his September 22 keynote in New Hampshire (following Chris Christie), where a similar council is being stood up.', null, 15),
  ('2026-09-02-gcsg-board-meeting', 'discussion', 'BOARD GOVERNANCE — Elisa is stepping back from her board seat; Alex Hall (representing Eight State) will take her seat instead of Elisa. Tareq''s potential board seat was raised, possibly tied to Matt/Eight State''s seat, given his increasing financial and time commitment — to be finalized by email vote rather than at this meeting. Bylaws require quarterly board meetings; Q3 meeting needs to be scheduled.', null, 16),
  ('2026-09-02-gcsg-board-meeting', 'decision', 'Kindbridge contract signed for $90K — limited initial scope (no $30K workforce-development add-on, no full treatment-coverage add-on) pending integration data.', 'Agreed', 17),
  ('2026-09-02-gcsg-board-meeting', 'decision', 'Avive contract signed — digital portal with cut-back/abstain pathways and an affected-others portal.', 'Agreed', 18),
  ('2026-09-02-gcsg-board-meeting', 'decision', 'Gamban contract received but not yet signed — remains under legal review.', 'Agreed', 19),
  ('2026-09-02-gcsg-board-meeting', 'decision', 'Monthly vendor engagement reporting (HIPAA-limited) begins in October across all three vendor contracts.', 'Agreed', 20),
  ('2026-09-02-gcsg-board-meeting', 'decision', 'Alex Hall to take the board seat previously earmarked for Elisa; Tareq''s potential board seat to be finalized via email vote at a later date.', 'Agreed', 21),
  ('2026-09-02-gcsg-board-meeting', 'decision', 'Board meetings to be held quarterly per bylaws; Q3 meeting to be scheduled.', 'Agreed', 22),
  ('2026-09-02-gcsg-board-meeting', 'decision', 'Membership program for operators to remain an informal, exploratory conversation for now — no formal program to be built until fit and dollar potential are clearer.', 'Agreed', 23),
  ('2026-09-02-gcsg-board-meeting', 'action', 'Brianne: Regain website admin access via former contractor (chase Kim/Phil for credentials) to redirect the helpline number', 'Brianne', 24),
  ('2026-09-02-gcsg-board-meeting', 'action', 'Brianne + Tareq: Join Kindbridge kickoff call with Dan Umfleet next week to establish workflow/integration', 'Brianne + Tareq', 25),
  ('2026-09-02-gcsg-board-meeting', 'action', 'Brianne: Coordinate joint press release/op-ed with Kindbridge for National Recovery Month (September), targeting AJC and local press', 'Brianne', 26),
  ('2026-09-02-gcsg-board-meeting', 'action', 'Brianne: Deliver clinical staffing/capacity report (via Kindbridge''s clinical director Michelle) by mid-October', 'Brianne', 27),
  ('2026-09-02-gcsg-board-meeting', 'action', 'Brianne: Report back to the board within 60 days with a data-informed recommendation on prevention vs. treatment resource allocation', 'Brianne', 28),
  ('2026-09-02-gcsg-board-meeting', 'action', 'Adam: Deliver New Hampshire keynote on September 22 (following Chris Christie); test "model council" and youth-protection framing', 'Adam', 29),
  ('2026-09-02-gcsg-board-meeting', 'action', 'Adam + Michael: Lead Spell Off investor fundraise next week; explore whether interest can also benefit GCSG', 'Adam + Michael', 30),
  ('2026-09-02-gcsg-board-meeting', 'action', 'Brianne + Adam: Revise donor/fundraising template letter to reflect signed vendor contracts and Tareq''s donation', 'Brianne + Adam', 31),
  ('2026-09-02-gcsg-board-meeting', 'action', 'Adam + Jonathan: Finalize board membership changes (Alex Hall''s seat, potential Tareq seat) via email vote', 'Adam + Jonathan', 32),
  ('2026-09-02-gcsg-board-meeting', 'action', 'Jonathan: Reconcile board meeting minutes with Adam''s notes and circulate to the group', 'Jonathan', 33),
  ('2026-09-02-gcsg-board-meeting', 'action', 'Group: Begin comparing calendars to schedule the Q3 board meeting', 'Group', 34),
  ('2026-08-26-gcsg-weekly', 'discussion', 'GAMBAN CONTRACT — Third and final contract has come in from Gamban. Brianne requested it in PDF format (not DocuSign) so lawyers can mark it up directly. Will send to Matt for legal review once received in PDF.', null, 1),
  ('2026-08-26-gcsg-weekly', 'discussion', 'KINDBRIDGE + EVIVE LEGAL REVIEW — Two lawyers reviewing (one per side), each had their own changes. They need to consolidate their suggestions before sending back to Brianne. Not expected to be controversial. Brianne pushing for same-day turnaround.', null, 2),
  ('2026-08-26-gcsg-weekly', 'discussion', 'BOARD MEETING LOCATION — Confirmed: WeWork in Midtown Atlanta (same room as the prior Miami meeting, just relocated). ~20 minute taxi from the airport. Matt will be there all day Tuesday — Tareq welcome to come work from there before the meeting.', null, 3),
  ('2026-08-26-gcsg-weekly', 'discussion', 'BOARD MEETING TIMING — Board meeting is next week (Tuesday). Weekly call for that Tuesday is being cancelled since the team will be together in person. Brianne traveling to London Saturday, returning Thursday night. Matt arrives Saturday night, will NOT be there in person — joining digitally due to family commitments.', null, 4),
  ('2026-08-26-gcsg-weekly', 'discussion', 'BRIANNE''S TRAVEL — Energy permitting forum in Columbus, Ohio right after the board meeting — hosted by Arnold Ventures (John & Laura Arnold), with Senator Cruz, Governor Abbott, Governor DeWine attending. Discussing sports betting, problem gambling, and federal/state funding policy with government officials.', null, 5),
  ('2026-08-26-gcsg-weekly', 'discussion', 'BOARD MEETING STRUCTURE — Matt''s guidance: keep it informal, not overly structured. Suggested 3 sections, ~15-20 min each: (1) Recap of progress/what''s been delivered, (2) Roadmap — where things are going with Evive, Gamban, etc., what the plan is by year-end, (3) Decisions/questions needing alignment. Should open with goals/objectives of the org so everything else ties back to that.', null, 6),
  ('2026-08-26-gcsg-weekly', 'discussion', 'BOARD DOCUMENTATION — No minutes exist from the last board meeting (it got moved). Matt can help create board minutes/documentation going forward. Adam doesn''t need super formal ''call to order'' procedures — keep it business-like but not bureaucratic.', null, 7),
  ('2026-08-26-gcsg-weekly', 'discussion', 'TWO CONTRACTS BEFORE BOARD MEETING — Brianne hopeful to have Kindbridge + Evive fully executed before the board meeting as a strong opening. Gamban would be noted as ''pending.''', null, 8),
  ('2026-08-26-gcsg-weekly', 'discussion', 'SEPTEMBER PRESS PUSH — Originally hoped for at least one announcement in September for Responsible Gaming Education Month. Brianne wants 10 minutes with Elisa at the board meeting to brainstorm the press push. Considering: full suite of services announced together vs. distinct announcements per vendor, or securing a deeper reporter story instead of a press release.', null, 9),
  ('2026-08-26-gcsg-weekly', 'discussion', 'PHASED PRESS STRATEGY — Team leaning toward phased announcements (multiple hits over time) rather than one big release. Order: lead with Kindbridge (it will become the new brand/phone number identity) — ''help and hope now exist in Georgia.'' Then Evive (digital interface) around the post-November election legalization conversations. Then Gamban tied to a ''new year, new journey to recovery'' framing. Not locked in — still a working thought process.', null, 10),
  ('2026-08-26-gcsg-weekly', 'discussion', 'KINDBRIDGE INTEGRATION — Brianne met with Dan Umflea (CEO of Kindbridge). Confirmed integration is not heavy: a 30-min intro call, then a 30-min call with the wider team, plus updating the new phone number and connectivity — no more than 1-2 hours of total integration work before live.', null, 11),
  ('2026-08-26-gcsg-weekly', 'discussion', 'WEBSITE ACCESS — Need to update site with the new phone number. Brianne recalled ''Kim'' helped with the site previously — needs to reconnect with Kim (and Celeste) to get credentials and, ideally, get the team direct CMS access so they aren''t blocked every time a small content change is needed (this was a recurring issue around the Super Bowl announcement).', null, 12),
  ('2026-08-26-gcsg-weekly', 'discussion', 'BOARD PACKET / DECK — Matt confirmed a digital packet of assets sent a few days ahead of the board meeting would be useful. Tareq and Brianne both already contributing to Michael''s existing deck rather than building a new one — rolling deck format where older content moves to an appendix over time. Goal: send something to Adam by close of business Friday.', null, 13),
  ('2026-08-26-gcsg-weekly', 'discussion', 'TAREQ''S ROADMAP QUESTIONS — Tareq wants clarity on: contract timelines, what the next 6 months / 1 year / 3 years looks like. Already has a running list of roadmap questions and structure prepared to add into the shared deck.', null, 14),
  ('2026-08-26-gcsg-weekly', 'discussion', 'COMMUNICATION PREFERENCES — Tareq asked Brianne how she prefers to be contacted — text, call, or email. Brianne: anytime, any format, even single quick questions are welcome (compared to saving up a long email).', null, 15),
  ('2026-08-26-gcsg-weekly', 'discussion', 'BOARD AGENDA ITEMS — Two items flagged for the ''decisions/questions'' section: (1) Adam Kaplan coming to town — expected to sign paperwork, (2) Matt''s board seat — discussion on whether Matt hands his board seat to Elisa now that she''s more involved. Quorum requirement to be confirmed for any vote needed.', null, 16),
  ('2026-08-26-gcsg-weekly', 'discussion', 'AGENDA SLIDE — Brianne to add an explicit agenda slide/bullet points for the 3 board meeting topics so the group doesn''t get sidetracked mid-discussion and miss a required item.', null, 17),
  ('2026-08-26-gcsg-weekly', 'decision', 'Gamban PDF contract requested — lawyers to mark up directly rather than DocuSign', 'Agreed', 18),
  ('2026-08-26-gcsg-weekly', 'decision', 'Board meeting confirmed: WeWork Midtown Atlanta, next Tuesday', 'Agreed', 19),
